from collections import deque

MOD = 10**9 + 7

def power(m, n, total_power):
    if n == 0:
        return 1 % MOD
    if n % 2 == 0:
        half_power = power(m, n // 2, total_power)
        return (half_power * half_power) % MOD
    else:
        two_power = power(m, n - 1, total_power)
        return (m * two_power) % MOD

class PowerTree:
    def __init__(self, v0, updates):
        self.total_power = [v0]
        self.powers = [v0]
        self.parent = [None]
        self.last_update = 0
        self.vertices_added = 1
        self.update_updates = deque([])
        self.update_queries = []
        self.tree = []
        self.process_updates(units, updates)

    def process_updates(self, units, updates):
        update_count = 0
        for entry in updates:
            if entry[0] == 1:
                self.update_updates.appendleft(entry)
            else:
                self.update_queries.append((entry, units))
                update_count += 1
            if update_count == units:
                units = len(self.update_updates)
                for entry in self.update_updates:
                    if entry[0] == 1:
                        self.add_vertex(entry)
                        self.build_tree()
                self.update_updates.clear()
                self.update_updates.appendleft(entry)
                units -= 1

    def add_vertex(self, update):
        if update[2] > self.vertices_added:
            self.vertices_added = update[2] + 1
        node = self.vertices_added
        for i in range(1, update[1] + 1):
            self.tree.append(deque(range(1, i + 1)))
            self.parent[node + i - 1] = node # set child to parent if min
            if i < update[1]:
                self.tree[node + i].appendleft(node - i) # children to parent
        self.tree.pop()
        self.root = node
        self.last_update = update[1] + 1

    def build_tree(self):
        last_rotation = 0
        for i in range(self.last_update):
            rotations = pow(2, self.last_update - i, self.vertices_added)
            total_child_power = 0
            for children in self.tree[i + 1]:
                for child in self.tree[children][1]:
                    total_child_power += self.powers[child]
            self.total_power.append((total_child_power + self.powers[last_rotation]) * rotations % MOD)
            self.powers.append(total_child_power * rotations % MOD)
            last_rotation = children
        self.powers[1:] = self.total_power
