from collections import deque

def can_form_polygon(n):
    # Create deque for circular list storage
    storage = deque(range(1, n+1))

    # Perform BFS to check connectivity
    size = len(storage)
    while len(storage) > 1:
        current = storage.popleft()
        distances = {}

        # Iterate till all vertices are reached
        for next in storage:
            distance = abs(current - next) % n
            distances[distance] = n - len(storage)
            if distance == 0:
                storage.remove(next)

            # Ensure there are no three collinear points
            if storage.count((next + 1) % n) >= 3 or storage.count((next + n - 1) % n) >= 3:
                return False
            while len(storage) > 1 and storage.count(storage[0]) >= 3:
                storage.remove(storage[0])

        storage.extend(storage.popleft())
        distances = [(d, k) for k, d in distances.items()]
        distances.sort()
        for current_count, next_count in distances:
            storage.insert(next_count, current_count)

    return True

# Calculate the maximum possible side length for a regular polygon
def max_side_length(storage):
    min_side = float('inf')
    while len(storage) > 1:
        current = storage.popleft()
        storage.extend(storage.popleft())
        if storage.count(storage[0]) >= 3:
            storage.remove(storage[0])
        min_side = min(min_side, abs(current - storage[1]) // 2)
    return min_side

def find_polygon_layout(n):
    if n % 2 == 0:
        return "NO"
    storage = [1, 2]
    max_side = max_side_length(storage)
    while not can_form_polygon(n):
        storage[1] += 1
        storage.extend(storage[1:])
        max_side = max_side_length(storage)
        if max_side > 10**9:
            break
        storage.append(storage[1] - 1)
        storage.remove(storage[1])
    if len(storage) != n or not can_form_polygon(n) or len(storage) <= 4:
        return "NO"
    return "YES"

def main():
