        return False
    for i in range(len(vertices) - 3):
        # If dot product of vectors is less than or equal to 0, points lie on the same line.
        if dot_product(vertices[i], vertices[i + 1], vertices[i + 2]) <= 0:
            return False
    return True

def dot_product(a, b, c):
