    time = [None] * (n + 1)
    time[0] = 0
    for i in range(1, n + 1):
        for pair in pairs:
            if i <= pair[0] and time[i] is None:
                time[i] = time[pair[0]] + len(pair[1])
                break
        else:
            time[i] = i
    return time

# Process the input and print the output
