import math
from collections import deque

def build_tree(h):
    tree = {}
    queue = deque([0])
    for level in range(1, h + 1):
        n = 2 ** (level - 1)
        for i in range(n):
            parent = queue.popleft()
            tree[parent] = []
            if i < n - 1:
                left = 2 * parent + 1
                if parent in tree:
                    tree[left].append(parent)
                if i + 1 < n:
                    right = 2 * parent + 2
                    if parent in tree:
                        tree[right].append(parent)
                queue.append(left)
                queue.append(right)
    return tree

def leaf_numbers(tree):
    numbers = []
    def traverse(node):
        if node in tree:
            numbers.append(node)
        if node in tree:
            for child in tree[node]:
                traverse(child)
    traverse(0)
    return numbers

def expectation_of_possibility(tree, removable_v, removable_e):
    if removable_v == 2 * removable_e + 1:
        return math.inf  # No lower bound possible

    r_tree = {v: [] for v in tree}  # Duplicate `r_tree` to modify values in-place

    root = 0
    while root in r_tree:
        while removable_v in r_tree[root]:
            r_tree[root].remove(removable_v)
            removable_v = 2 * removable_v + 1  # Potential new basis for choice
        choice = math.inf
        if removable_v in r_tree:
            ll = 2 ** (r_tree[root][-1] // 2 - 1)
            ll += max(len(x) for x in r_tree[removable_v] if len(x) <= ll)
            choice = ll
            tree[root] = r_tree[root]
        if r_tree[root]:
            candidate = math.inf
            for c in r_tree[root]:
                nn = len(r_tree[c])
                if nn > 3:
                    candidate = f"-inf"
                else:
                    childchoice = expectation_of_possibility(r_tree, choice, removable_e)
                    choice = max(choice, childchoice)
                candidate = min(candidate, childchoice)
            if childchoice != -inf:
                choice = min(choice, childchoice)
        if choice in ["-inf", math.inf]:
            return choice
        elif choice == -inf:
            r_tree[root].extend(choice)
        return choice

    return math.inf  # Should never reach here

