import math

def is_convex_polygon(vertices, n):
    for i in range(n-1):
        if (_cross_product(vertices[i+1], vertices[i]) * _cross_product(vertices[i], vertices[(i+1) % n]) <= 0):
            return False
    if (_cross_product(vertices[n-1], vertices[0]) * _cross_product(vertices[0], vertices[(n-1) % n]) <= 0):
        return False
    return True

def _cross_product(v1, v2):
    return (v1[0] * v2[1] - v1[1] * v2[0])

def find_maximal_side_convex(n):
    if n == 3:
        return 1, (0, 0), (1, 0), (0, 1)

    max_side = 1
    vertices = [(0, 0)] * n
    x_diffs = [1]
    y_diffs = [1]

    for i in range(n):
        x_diffs.append(+1 if (i % 2 == 0) == y_diffs[-1] else -1)
        y_diffs.append(+1 if (i % 2 == 0) == x_diffs[-1] else -1)

    for sides_count in range(3, n+1):
        for start_vertex in range(n**2 // sides_count):
            origin = (start_vertex % n, start_vertex // n)
            for i in range(sides_count):
                start_vertex += 1
                origin[1] = (origin[1] + y_diffs[i]) % n
                origin[0] = (origin[0] + x_diffs[i]) % n
            if is_convex_polygon([origin for _ in range(sides_count)], n):
                for coord in origin:
                    if coord < -109_952 or coord > 109_951:
