            if k % 2 == 0:
                first_vertex = (0, edge)
            else:
                first_vertex = (edge + k, 0)

        print(f"{abs(current_x)} {abs(current_y)}")

    prev_x, prev_y = first_vertex

    for _ in range(2):
        for edge in range(n, 0, -1):
