from math import sqrt

mod = 998244353

def power(x, y, mod):
    res = 1
    x = x % mod
    while y > 0:
        if y % 2 == 1:
            res = (res * x) % mod
        y = y//2
        x = (x * x) % mod
    return res

def lucky_count(n):
    p, q = 3, 0
    combinations = power(2, pow(2, n, mod) - 2, mod)
    if n % 2 == 0:
        p = pow(2, n//2, mod)
        for k in range(3, n, 2):
            q += power(2, k//2, mod)
            if k % 4 == 0:
                q -= power(4, k//4, mod)
            if k % 8 == 0:
                q += power(2, (k//8)//2, mod)
            q %= mod
    else:
        for k in range(2, n, 2):
            q += power(p, k//2, mod)
            if k % 4 == 0:
                q -= combinations
            if k % 8 == 0:
                q += combinations * power(p, k//8, mod) % mod
            q %= mod
    return (combinations - q) % mod

n = int(input().strip())
